package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.std.NumberSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class NumberSerializer_acceptJsonFormatVisitor_TriageGen1Test {

    @Test
    public void testAcceptJsonFormatVisitor_IntBranch() throws JsonMappingException {
        // We need to trigger the _isInt = true branch. 
        // Since _isInt is likely private and set via constructor or internal logic, 
        // we use the specific subclass/type that triggers it: Integer or Long.
        // In Jackson's NumberSerializer, passing Integer.class sets _isInt to true.

        NumberSerializer serializer = new NumberSerializer(Integer.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // Spy to verify the call to visitIntFormat (which is a protected method in the same class)
        NumberSerializer spySerializer = spy(serializer);

        spySerializer.acceptJsonFormatVisitor(visitor, typeHint);

        // visitIntFormat eventually calls visitor.expectIntFormat or similar.
        // Based on the provided code, if _isInt is true, it calls visitIntFormat(..., BIG_INTEGER)
        // We verify the behavior by checking if the visitor was interacted with.
        // Since we can't easily verify protected method calls without more setup, 
        // we ensure the code path executes without exception.
        verify(visitor, times(0)).expectNumberFormat(any());
    }

    @Test
    public void testAcceptJsonFormatVisitor_BigDecimalBranch() throws JsonMappingException {
        // Trigger the ((Class<?>) handledType()) == BigDecimal.class branch
        NumberSerializer serializer = new NumberSerializer(BigDecimal.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // visitFloatFormat(..., BIG_DECIMAL) is called.
        // We verify that it didn't go into the 'else' block of the second if.
        verify(visitor, times(0)).expectNumberFormat(any());
    }

    @Test
    public void testAcceptJsonFormatVisitor_OtherNumberBranch() throws JsonMappingException {
        // Trigger the final else block: visitor.expectNumberFormat(typeHint)
        // Using Double.class which is not Int and not BigDecimal
        NumberSerializer serializer = new NumberSerializer(Double.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Verify the final else branch was hit
        verify(visitor, times(1)).expectNumberFormat(typeHint);
    }

    @Test(expected = JsonMappingException.class)
    public void testAcceptJsonFormatVisitor_ThrowsException() throws JsonMappingException {
        // Test exception propagation
        NumberSerializer serializer = new NumberSerializer(Double.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        doThrow(new JsonMappingException(null, "error")).when(visitor).expectNumberFormat(any());

        serializer.acceptJsonFormatVisitor(visitor, typeHint);
    }
}
